import { describe, expect, it } from 'vitest'
import { loadPrecExample } from './precOps'
import { defaultProjectData, type ProjectData } from './project'
import { TEXT_EXPORT_KINDS, analyzeProject } from './projectAnalysis'

const TEXTBOOK = `E  -> T E'
E' -> + T E' | ε
T  -> F T'
T' -> * F T' | ε
F  -> ( E ) | i`

function project(grammar = TEXTBOOK): ProjectData {
  const d = loadPrecExample(defaultProjectData())
  return { ...d, ll: { grammar, input: 'i + i' } }
}

describe('analyzeProject – LL side', () => {
  it('gives the LL table of the grammar rules with conflicting cells marked', () => {
    const a = analyzeProject(project('S -> a | a b'))
    expect(a.llTable?.header).toEqual(['', 'a', 'b', '$'])
    expect(a.llTable?.rows[0]).toMatchObject({ head: 'S', cells: [{ text: '1, 2', conflict: true }, { text: '' }, { text: '' }] })
  })

  it('gives the Empty, First, Follow and Predict sets', () => {
    const a = analyzeProject(project())
    expect(a.sets?.nonterminals.find((n) => n.nonterminal === "E'")).toEqual({
      nonterminal: "E'",
      empty: true,
      first: ['+'],
      follow: [')', '$'],
    })
    expect(a.sets?.predict[0]).toEqual({ rule: 1, text: "E → T E'", predict: ['(', 'i'] })
  })

  it('has no LL table or sets without grammar rules', () => {
    const a = analyzeProject(defaultProjectData())
    expect(a.llTable).toBeNull()
    expect(a.sets).toBeNull()
    expect(a.simulateLL('i')).toBeNull()
  })

  it('lists the definition and LL problems', () => {
    const a = analyzeProject({ ...project('S -> a | a b'), def: { nonterminals: 'S', terminals: 'a', start: '' } })
    expect(a.problems.ll).toContainEqual({ level: 'bad', text: 'Konflikt [S, a]: pravidlá 1, 2' })
    expect(a.problems.definition.some((p) => p.level === 'bad' && p.text.startsWith('Symbol b'))).toBe(true)
  })
})

describe('analyzeProject – precedence side', () => {
  it('gives the precedence table as a grid of relations including $', () => {
    const a = analyzeProject(project())
    expect(a.precTable.columns).toEqual(['i', '+', '*', '(', ')', '$'])
    expect(a.precTable.rows[5]).toEqual({ terminal: '$', relations: ['<', '<', '<', '<', '', ''] })
  })

  it('lists the precedence problems', () => {
    const a = analyzeProject({ ...project(), prec: { ...project().prec, rules: 'E -> E + E\nE -> E + E' } })
    expect(a.problems.prec).toContainEqual({ level: 'bad', text: 'Pravidlá 1 a 2 majú rovnakú pravú stranu (E + E)' })
  })
})

describe('analyzeProject – simulations run on an input passed in, never the content', () => {
  it('runs the LL simulation on the given input', () => {
    const d = project()
    const before = structuredClone(d)
    const sim = analyzeProject(d).simulateLL('i * i')
    expect(sim?.ok).toBe(true)
    expect(sim?.rows[0].input).toBe('i * i $')
    expect(d).toEqual(before)
  })

  it('runs the precedence simulation on the given input, not on the saved one', () => {
    const d = project()
    const before = structuredClone(d)
    const a = analyzeProject(d)
    expect(a.simulatePrec('( i')?.ok).toBe(false)
    expect(a.simulatePrec('i * ( i + i )')).toMatchObject({ ok: true, message: 'Úspech. Pravý rozbor: 4 4 4 1 3 2' })
    expect(a.simulatePrec('')).toBeNull()
    expect(d).toEqual(before)
  })
})

describe('analyzeProject – text exports', () => {
  it('produces every text export (Markdown, CSV, LaTeX, C) without a browser', () => {
    expect(typeof document).toBe('undefined')
    const a = analyzeProject(project())
    expect(TEXT_EXPORT_KINDS).toEqual(['def-md', 'def-tex', 'll-md', 'll-sets-md', 'll-csv', 'll-tex', 'll-c', 'prec-md', 'prec-csv', 'prec-tex', 'prec-c'])
    for (const kind of TEXT_EXPORT_KINDS) expect(a.export(kind).type, kind).toBe('text')
  })

  it('uses the export naming of the content in C headers', () => {
    const d = project()
    const out = analyzeProject({ ...d, names: { ...d.names, precPrefix: 'OP_' } }).export('prec-c')
    expect(out.type === 'text' && out.text).toContain('OP_PLUS')
  })

  it('reports an empty table instead of exporting it', () => {
    expect(analyzeProject(defaultProjectData()).export('ll-csv')).toEqual({ type: 'error', error: 'LL gramatika je prázdna.' })
  })
})
